import { resolvers } from '@hozu/data'
import { app } from '@hozu/runtime-server'
import project from './hozu.config.ts'
import { createNumbers, createStore, notesResolvers, ownedCounts, type Deleted } from './features/notes/server.ts'
import { adminResolvers } from './features/admin/server.ts'
import { accountResolvers } from './features/account/server.ts'

// Undo of the last delete, per user; signing out forgets it.
const deleted: Deleted = new Map()
const store = createStore()
const numbers = createNumbers()
// Everyone who has signed in, for the admin page.
const seen = new Set<string>()

export default app({
  resolvers: resolvers(project, (implement) => [
    ...accountResolvers(
      implement,
      (user) => deleted.delete(user),
      (user) => seen.add(user),
      // Deleting an account drops the user's notes (shared ones vanish for their recipients) and forgets the user.
      (user) => {
        store.delete(user)
        numbers.delete(user)
        deleted.delete(user)
        seen.delete(user)
      },
    ),
    ...notesResolvers(implement, deleted, store, numbers),
    ...adminResolvers(implement, () => ownedCounts(store), seen),
  ]),
})
import { feature } from '@hozu/core'
import { account } from '../account/feature.ts'
import * as model from './model.ts'
import * as views from './views.ts'

export const adminFeature = feature({
  id: 'admin',
  intent: { summary: 'The user `admin` sees every user and how many notes each owns' },
  imports: [account],
  declarations: [model, views],
})
import { query } from '@hozu/core'
import { z } from 'zod'

export const UserRow = z.object({ name: z.string(), notes: z.number() })

// Every user who has signed in or owns notes, with how many notes they own (archived ones included). Only `admin`.
export const listUsers = query({
  input: z.object({}),
  output: z.array(UserRow),
  errors: { Unauthorized: z.object({}), NotAdmin: z.object({}) },
  scope: 'user',
  freshness: 'request',
  runs: 'server',
  access: 'anyone',
})
import type { Implement } from '@hozu/data'
import { listUsers } from './model.ts'

// `owned` counts each owner's notes (archived included); `seen` is everyone who has signed in.
export function adminResolvers<Env>(implement: Implement<{ user: string }, Env>, owned: () => Map<string, number>, seen: Set<string>) {
  return [
    implement(listUsers, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      if (session.user !== 'admin') return fail('NotAdmin', {})
      const counts = owned()
      for (const user of seen) if (!counts.has(user)) counts.set(user, 0)
      return [...counts].map(([name, notes]) => ({ name, notes })).sort((a, b) => a.name.localeCompare(b.name))
    }),
  ]
}
import { ui } from '@hozu/core'
import { admin } from '../../routes.ts'
import { me } from '../account/model.ts'
import { listUsers } from './model.ts'

// On the list page: a link to the admin page, for the user `admin` only.
export const AdminLink = ui.view({
  render: () =>
    ui.nav({ class: 'mx-auto max-w-xl px-4 pt-2 text-sm' }, [
      ui.query(
        me,
        {},
        {
          ready: (user) => (user.name === 'admin' ? ui.a({ href: ui.link(admin, null), class: 'underline' }, ['Admin']) : null),
          failed: { Unauthorized: () => null, Unexpected: () => null },
        },
      ),
    ]),
})

export const AdminBoard = ui.view({
  route: admin,
  render: () =>
    ui.main({ class: 'mx-auto max-w-xl space-y-6 px-4 py-12' }, [
      ui.h1({ class: 'text-3xl font-bold' }, ['Admin']),
      ui.query(
        listUsers,
        {},
        {
          ready: (users) =>
            ui.table({ class: 'w-full text-left' }, [
              ui.thead({}, [ui.tr({}, [ui.th({ class: 'py-2' }, ['User']), ui.th({ class: 'py-2' }, ['Notes'])])]),
              ui.tbody({}, [
                ui.each(users, 'name', (u) => ui.tr({ class: 'border-t' }, [ui.td({ class: 'py-2' }, [u.name]), ui.td({ class: 'py-2' }, [u.notes])])),
              ]),
            ]),
          failed: {
            Unauthorized: () => ui.p({ role: 'alert' }, ['Sign in first']),
            NotAdmin: () => ui.p({ role: 'alert' }, ['Not allowed']),
            Unexpected: () => ui.p({ role: 'alert' }, ['Unavailable']),
          },
        },
      ),
    ]),
})
import { project, ui } from '@hozu/core'
import { zodAdapter } from '@hozu/schema-zod'
import { accountDelete, admin, archive, home, login, notePage } from './routes.ts'
import { AdminBoard, AdminLink } from './features/admin/views.ts'
import { listUsers } from './features/admin/model.ts'
import { adminFeature } from './features/admin/feature.ts'
import { ArchiveBoard, NotesBoard, NoteView, notesText } from './features/notes/views.ts'
import { notes } from './features/notes/feature.ts'
import { getNote } from './features/notes/model.ts'
import { me, Session } from './features/account/model.ts'
import { AccountBar, accountText, DeleteAccountPage, Login } from './features/account/views.ts'
import { account } from './features/account/feature.ts'

export default project({
  schema: zodAdapter,
  session: Session,
  styles: new URL('./app.css', import.meta.url),
  app: new URL('./app.ts', import.meta.url),
  env: { files: ['.env', '.env.local'] },
  site: { url: 'http://localhost:3000', name: 'app', lang: 'en', locales: ['en', 'de'] },
  routes: { home, login, archive, admin, accountDelete, notePage },
  pages: [
    ui.page(login, { views: [Login], head: { render: () => ({ title: accountText.signIn }) } }),
    ui.page(home, {
      views: [AccountBar, AdminLink, NotesBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: notesText.notes, noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(archive, {
      views: [AccountBar, ArchiveBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Archive', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(notePage, {
      views: [NoteView],
      head: {
        query: getNote,
        input: (params) => ({ number: params.number }),
        render: (note) => ({ title: note.title, noindex: true }),
        failed: { Forbidden: login, NotFound: 404 },
      },
    }),
    ui.page(accountDelete, {
      views: [DeleteAccountPage],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Delete account', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(admin, {
      views: [AccountBar, AdminBoard],
      head: {
        query: listUsers,
        input: () => ({}),
        render: () => ({ title: 'Admin', noindex: true }),
        failed: { Unauthorized: login, NotAdmin: 403 },
      },
    })],
  features: [account, notes, adminFeature],
})
