import { endpoint, event, fn, invoke, machine, mutation, on, query, tag } from '@hozu/core'
import { z } from 'zod'

export const Note = z.object({
  id: z.string(),
  title: z.string(),
  pinned: z.boolean(),
  createdAt: z.string(),
  number: z.number(),
  sharedWith: z.array(z.string()),
  body: z.string(),
})
// A note another user shared with the signed-in user: only what the recipient may see.
export const SharedNote = z.object({ id: z.string(), title: z.string(), owner: z.string() })
export const ShareName = z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters')
export const NoteKey = z.object({ id: z.string() })
export const NewNote = z.object({
  title: z.string().trim().min(1, 'Write a note').max(60, 'Use at most 60 characters'),
})

export const Draft = event({ payload: z.object({ title: z.string() }) })
export const Add = event({ payload: z.object({ title: z.string() }) })
export const Remove = event({ payload: NoteKey })
export const Pin = event({ payload: NoteKey })
export const Search = event({ payload: z.object({ q: z.string() }) })
export const Edit = event({ payload: NoteKey })
export const CancelEdit = event({ payload: z.object({}) })
export const Save = event({ payload: z.object({ id: z.string(), title: z.string() }) })
export const SaveNote = event({ payload: z.object({ id: z.string(), title: z.string(), body: z.string() }) })
export const Archive = event({ payload: NoteKey })
export const Restore = event({ payload: NoteKey })
export const Undo = event({ payload: NoteKey })
export const Select = event({ payload: z.object({ id: z.string(), checked: z.boolean() }) })
export const Share = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const Unshare = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const BulkAction = z.enum(['delete', 'archive'])
export const Bulk = event({ payload: z.object({ ids: z.array(z.string()), action: BulkAction }) })

export const notesTag = tag({ param: null })

// The signed-in user's own notes (archived ones included, shared-with-me ones not), in the list page's order.
export const ExportedNote = z.object({
  title: z.string(),
  pinned: z.boolean(),
  archived: z.boolean(),
  createdAt: z.string(),
})
export const exportNotes = endpoint({
  method: 'GET',
  path: '/api/export',
  input: z.object({}),
  output: z.object({ user: z.string(), notes: z.array(ExportedNote) }),
  errors: { Unauthorized: z.object({ message: z.string() }) },
  failed: { Unauthorized: 401 },
})

export const listNotes = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

// One of the signed-in user's own notes (archived ones included), by its number; shared notes never.
export const NoteDetail = Note.extend({ archived: z.boolean() })
export const getNote = query({
  input: z.object({ number: z.string() }),
  output: NoteDetail,
  errors: { NotFound: z.object({ number: z.string() }) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'signedIn',
})

export const listArchived = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const addNote = mutation({
  input: NewNote,
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), TooMany: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const removeNote = mutation({
  input: NoteKey,
  output: NoteKey,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const togglePin = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const renameNote = mutation({
  input: z.object({ id: z.string(), title: NewNote.shape.title }),
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

// Saves a note's title and body from its page; the resolver checks both fields and reports every message at once.
export const updateNote = mutation({
  input: z.object({ id: z.string(), title: z.string(), body: z.string() }),
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const archiveNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const restoreNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

// Notes other users shared with the signed-in user (not archived, not deleted).
export const listShared = query({
  input: z.object({}),
  output: z.array(SharedNote),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const shareNote = mutation({
  input: z.object({ id: z.string(), name: ShareName }),
  output: Note,
  errors: { NotFound: NoteKey, Archived: NoteKey, Self: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const unshareNote = mutation({
  input: z.object({ id: z.string(), name: z.string() }),
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

// The user's most recent delete, while it can still be undone.
export const lastDeleted = query({
  input: z.object({}),
  output: z.object({ id: z.string(), title: z.string() }).nullable(),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const undoRemove = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

// Bulk actions skip notes that are gone or already archived. A bulk delete cannot be undone.
export const removeNotes = mutation({
  input: z.object({ ids: z.array(z.string()).min(1, 'Select at least one note') }),
  output: z.object({ count: z.number() }),
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

export const archiveNotes = mutation({
  input: z.object({ ids: z.array(z.string()).min(1, 'Select at least one note') }),
  output: z.object({ count: z.number() }),
  invalidates: () => [notesTag()],
  runs: 'server',
  access: 'anyone',
})

const matches = (note: { title: string }, q: string) => note.title.toLowerCase().includes(q.trim().toLowerCase())

export const matching = fn({
  input: z.object({ items: z.array(Note), q: z.string() }),
  output: z.array(Note),
  impl: ({ items, q }) => items.filter((note) => matches(note, q)),
})

export const noneMatch = fn({
  input: z.object({ items: z.array(Note), q: z.string() }),
  output: z.boolean(),
  impl: ({ items, q }) => !items.some((note) => matches(note, q)),
})

// The first `limit` notes the URL filters select, in list order; "Load more" raises the limit.
export const firstMatching = fn({
  input: z.object({ items: z.array(Note), q: z.string(), limit: z.number() }),
  output: z.array(Note),
  impl: ({ items, q, limit }) => items.filter((note) => matches(note, q)).slice(0, limit),
})

export const countMatching = fn({
  input: z.object({ items: z.array(Note), q: z.string() }),
  output: z.number(),
  impl: ({ items, q }) => items.filter((note) => matches(note, q)).length,
})

export const addedOn = fn({
  input: z.object({ at: z.string() }),
  output: z.string(),
  impl: ({ at }) => new Date(at).toISOString().slice(0, 10),
})

export const NOTHING_TO_UNDO = 'There is nothing to undo'
export const DUPLICATE = 'You already have a note with this title'
export const TOO_MANY = 'Too many notes, try again in a minute'
export const NOT_FOUND = 'This note no longer exists'
export const ARCHIVED = 'This note is archived'
export const SHARE_SELF = 'You cannot share with yourself'

export const notesMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ title: z.string().nullable() }),
    target: z.string(),
    shareName: z.string(),
    q: z.string(),
    editing: z.string(),
    editTitle: z.string(),
    editError: z.string().nullable(),
    selected: z.array(z.string()),
    noteTitle: z.string(),
    noteBody: z.string(),
    noteTyped: z.boolean(),
    noteFields: z.object({ title: z.string().nullable(), body: z.string().nullable() }),
    noteError: z.string().nullable(),
    noteSaved: z.boolean(),
  }),
  initialContext: {
    draft: '', error: null, fields: { title: null }, target: '', shareName: '', q: '', editing: '', editTitle: '', editError: null, selected: [],
    noteTitle: '', noteBody: '', noteTyped: false, noteFields: { title: null, body: null }, noteError: null, noteSaved: false,
  },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(Draft, { target: 'idle', assign: (e) => { ctx.draft = e.title } }),
        on(Add, {
          target: 'adding',
          assign: (e) => {
            ctx.draft = e.title
            ctx.error = null
            ctx.fields = { title: null }
          },
        }),
        on(Remove, { target: 'removing', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Pin, { target: 'pinning', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Archive, { target: 'archiving', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Select, { target: 'idle', guard: (e) => e.checked === true, assign: (e) => { ctx.selected = ctx.selected.filter((id) => id !== e.id); ctx.selected.push(e.id) } }),
        on(Select, { target: 'idle', assign: (e) => { ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Bulk, { target: 'removingMany', guard: (e) => e.ids.length > 0 && e.action === 'delete', assign: (e) => { ctx.selected = e.ids; ctx.error = null } }),
        on(Bulk, { target: 'archivingMany', guard: (e) => e.ids.length > 0 && e.action === 'archive', assign: (e) => { ctx.selected = e.ids; ctx.error = null } }),
        on(Bulk, { target: 'idle' }),
        on(Share, { target: 'sharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Unshare, { target: 'unsharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Restore, { target: 'restoring', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Undo, { target: 'undoing', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Search, { target: 'idle', assign: (e) => { ctx.q = e.q } }),
        on(Edit, { target: 'idle', assign: (e) => { ctx.editing = e.id; ctx.editError = null } }),
        on(CancelEdit, { target: 'idle', assign: () => { ctx.editing = ''; ctx.editError = null } }),
        on(Save, {
          target: 'saving',
          assign: (e) => {
            ctx.editing = e.id
            ctx.editTitle = e.title
            ctx.editError = null
            ctx.error = null
          },
        }),
        on(SaveNote, {
          target: 'savingNote',
          assign: (e) => {
            ctx.target = e.id
            ctx.noteTitle = e.title
            ctx.noteBody = e.body
            ctx.noteTyped = true
            ctx.noteFields = { title: null, body: null }
            ctx.noteError = null
            ctx.noteSaved = false
          },
        }),
      ],
    },
    savingNote: {
      invoke: invoke(updateNote, {
        input: { id: ctx.target, title: ctx.noteTitle, body: ctx.noteBody },
        done: { target: 'idle', assign: () => { ctx.noteTyped = false; ctx.noteSaved = true } },
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.noteError = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.noteError = ARCHIVED } },
          Invalid: { target: 'idle', assign: (e) => { ctx.noteFields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.noteError = e.message } },
        },
      }),
    },
    adding: {
      invoke: invoke(addNote, {
        input: { title: ctx.draft },
        done: { target: 'idle', assign: () => { ctx.draft = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.error = DUPLICATE } },
          TooMany: { target: 'idle', assign: () => { ctx.error = TOO_MANY } },
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    saving: {
      invoke: invoke(renameNote, {
        input: { id: ctx.editing, title: ctx.editTitle },
        done: { target: 'idle', assign: () => { ctx.editing = ''; ctx.editTitle = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.editError = DUPLICATE } },
          NotFound: { target: 'idle', assign: () => { ctx.editing = ''; ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.editing = ''; ctx.error = ARCHIVED } },
          Invalid: { target: 'idle', assign: (e) => { ctx.editError = e.fields.title } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.editError = e.message } },
        },
      }),
    },
    removing: {
      invoke: invoke(removeNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    pinning: {
      invoke: invoke(togglePin, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    archiving: {
      invoke: invoke(archiveNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    sharing: {
      invoke: invoke(shareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Self: { target: 'idle', assign: () => { ctx.error = SHARE_SELF } },
          Invalid: { target: 'idle', assign: (e) => { ctx.error = e.fields.name } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    unsharing: {
      invoke: invoke(unshareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    restoring: {
      invoke: invoke(restoreNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    removingMany: {
      invoke: invoke(removeNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = [] } },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.selected = []; ctx.error = e.message } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    archivingMany: {
      invoke: invoke(archiveNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = [] } },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.selected = []; ctx.error = e.message } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    undoing: {
      invoke: invoke(undoRemove, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOTHING_TO_UNDO } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
  }),
})
import type { Implement } from '@hozu/data'
import { exportNotes, getNote, listShared, shareNote, unshareNote, addNote, archiveNote, archiveNotes, removeNotes, lastDeleted, listArchived, listNotes, removeNote, renameNote, updateNote, restoreNote, togglePin, undoRemove } from './model.ts'

type Stored = { id: string; title: string; pinned: boolean; createdAt: string; number: number; archived: boolean; sharedWith: string[]; body: string }
const shown = ({ archived: _, ...item }: Stored) => ({ ...item, sharedWith: [...item.sharedWith] })

// Per user: the most recently deleted note and where it stood, until the notes change again or the user signs out.
export type Deleted = Map<string, { item: Stored; at: number }>

export type Store = Map<string, Stored[]>
export const createStore = (): Store =>
  new Map<string, Stored[]>([
    ['ada', [{ id: 'n1', title: 'Buy milk', pinned: false, createdAt: '2026-01-15T09:00:00.000Z', number: 2, archived: false, sharedWith: [], body: '' }, { id: 'n2', title: 'Call Bob', pinned: false, createdAt: '2026-01-14T09:00:00.000Z', number: 1, archived: false, sharedWith: [], body: '' }]],
    ['bob', [{ id: 'n3', title: "Bob's secret", pinned: false, createdAt: '2026-01-10T09:00:00.000Z', number: 1, archived: false, sharedWith: [], body: '' }]],
  ])

// Per user: the highest note number the user has ever had; numbers are never reused, until the account is deleted.
export type Numbers = Map<string, number>
export const createNumbers = (): Numbers => new Map([['ada', 2], ['bob', 1]])

// How many notes each owner holds, archived ones included.
export const ownedCounts = (store: Store) => new Map([...store].map(([user, items]) => [user, items.length] as const))

export function notesResolvers<Env>(implement: Implement<{ user: string }, Env>, deleted: Deleted, store: Store, numbers: Numbers) {
  const listOf = (session: { user: string } | null): Stored[] => (session ? (store.get(session.user) ?? []) : [])
  const ownListOf = (session: { user: string } | null) => {
    if (!session) return []
    const list = store.get(session.user) ?? []
    store.set(session.user, list)
    return list
  }
  const changed = (session: { user: string } | null) => {
    if (session) deleted.delete(session.user)
  }
  // Per user: when each recently added note was added, for the limit of ADD_LIMIT adds per ADD_WINDOW_MS.
  const ADD_LIMIT = 10
  const ADD_WINDOW_MS = 60_000
  const added = new Map<string, number[]>()
  const recentAdds = (user: string, now: number) => {
    const recent = (added.get(user) ?? []).filter((at) => now - at < ADD_WINDOW_MS)
    added.set(user, recent)
    return recent
  }
  let seq = 3
  return [
    implement(listNotes, (_, { session, fail }) =>
      session
        ? [...listOf(session).filter((item) => !item.archived && item.pinned), ...listOf(session).filter((item) => !item.archived && !item.pinned)].map(shown)
        : fail('Unauthorized', {}),
    ),
    implement(getNote, ({ number }, { session, fail }) => {
      const item = listOf(session).find((note) => String(note.number) === number)
      return item ? { ...shown(item), archived: item.archived } : fail('NotFound', { number })
    }),
    implement(exportNotes, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      const items = listOf(session)
      return {
        user: session.user,
        notes: [...items.filter((item) => item.pinned), ...items.filter((item) => !item.pinned)].map((item) => ({
          title: item.title,
          pinned: item.pinned,
          archived: item.archived,
          createdAt: new Date(item.createdAt).toISOString(),
        })),
      }
    }),
    implement(listArchived, (_, { session, fail }) =>
      session
        ? listOf(session)
          .filter((item) => item.archived)
          .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || Number(b.id.slice(1)) - Number(a.id.slice(1)))
          .map(shown)
        : fail('Unauthorized', {}),
    ),
    implement(addNote, ({ title }, { fail, session }) => {
      const items = ownListOf(session)
      if (!session) return fail('Invalid', { message: 'Signed out', fields: { title: 'Sign in first' } })
      const clean = title.trim()
      if (items.some((item) => item.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      const now = Date.now()
      const recent = recentAdds(session.user, now)
      if (recent.length >= ADD_LIMIT) return fail('TooMany', {})
      recent.push(now)
      const number = Math.max(numbers.get(session.user) ?? 0, ...items.map((note) => note.number)) + 1
      numbers.set(session.user, number)
      const item = { id: `n${++seq}`, title: clean, pinned: false, createdAt: new Date().toISOString(), number, archived: false, sharedWith: [], body: '' }
      items.unshift(item)
      changed(session)
      return shown(item)
    }),
    implement(removeNote, ({ id }, { fail, session }) => {
      const items = ownListOf(session)
      const at = items.findIndex((item) => item.id === id)
      if (at < 0) return fail('NotFound', { id })
      if (items[at]?.archived) return fail('Archived', { id })
      const [item] = items.splice(at, 1)
      if (session && item) deleted.set(session.user, { item, at })
      return { id }
    }),
    implement(renameNote, ({ id, title }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((note) => note.id !== id && note.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      changed(session)
      return shown(item)
    }),
    implement(updateNote, ({ id, title, body }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const cleanTitle = title.trim()
      const cleanBody = body.trim()
      const fields = {
        title:
          cleanTitle.length === 0 ? 'Write a title first'
          : cleanTitle.length > 60 ? 'Use at most 60 characters'
          : items.some((note) => note.id !== id && note.title.toLowerCase() === cleanTitle.toLowerCase()) ? 'You already have a note with this title'
          : null,
        body: cleanBody.length > 1000 ? 'Use at most 1000 characters in the body' : null,
      }
      if (fields.title !== null || fields.body !== null)
        return fail('Invalid', { message: fields.title ?? fields.body ?? 'Invalid', fields })
      item.title = cleanTitle
      item.body = cleanBody
      changed(session)
      return shown(item)
    }),
    implement(togglePin, ({ id }, { fail, session }) => {
      const item = listOf(session).find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.pinned = !item.pinned
      changed(session)
      return shown(item)
    }),
    implement(archiveNote, ({ id }, { fail, session }) => {
      const item = listOf(session).find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.archived = true
      changed(session)
      return shown(item)
    }),
    implement(restoreNote, ({ id }, { fail, session }) => {
      const item = listOf(session).find((note) => note.id === id && note.archived)
      if (!item) return fail('NotFound', { id })
      item.archived = false
      changed(session)
      return shown(item)
    }),
    implement(removeNotes, ({ ids }, { session }) => {
      const items = ownListOf(session)
      const before = items.length
      items.splice(0, items.length, ...items.filter((item) => !ids.includes(item.id) || item.archived))
      changed(session)
      return { count: before - items.length }
    }),
    implement(archiveNotes, ({ ids }, { session }) => {
      const picked = listOf(session).filter((item) => ids.includes(item.id) && !item.archived)
      for (const item of picked) item.archived = true
      changed(session)
      return { count: picked.length }
    }),
    implement(listShared, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const shared: { id: string; title: string; owner: string }[] = []
      for (const [owner, items] of store)
        for (const item of items)
          if (owner !== session.user && !item.archived && item.sharedWith.includes(session.user))
            shared.push({ id: item.id, title: item.title, owner })
      return shared
    }),
    implement(shareNote, ({ id, name }, { fail, session }) => {
      const item = listOf(session).find((note) => note.id === id)
      if (!session || !item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const user = name.trim().toLowerCase()
      if (user === session.user) return fail('Self', {})
      if (!item.sharedWith.includes(user)) item.sharedWith.push(user)
      changed(session)
      return shown(item)
    }),
    implement(unshareNote, ({ id, name }, { fail, session }) => {
      const item = listOf(session).find((note) => note.id === id)
      if (!item) return fail('NotFound', { id })
      const user = name.trim().toLowerCase()
      item.sharedWith = item.sharedWith.filter((n) => n !== user)
      changed(session)
      return shown(item)
    }),
    implement(lastDeleted, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const last = deleted.get(session.user)
      return last ? { id: last.item.id, title: last.item.title } : null
    }),
    implement(undoRemove, ({ id }, { fail, session }) => {
      const last = session ? deleted.get(session.user) : undefined
      if (!session || !last || last.item.id !== id) return fail('NotFound', { id })
      const items = ownListOf(session)
      items.splice(Math.min(last.at, items.length), 0, last.item)
      deleted.delete(session.user)
      return shown(last.item)
    }),
  ]
}

