import { feature } from '@hozu/core'
import * as model from './model.ts'
import * as views from './views.ts'

export const account = feature({
  id: 'account',
  intent: { summary: 'Sign in with a name, sign out; the session identifies the user' },
  exports: [model.me],
  declarations: [model, views],
})
import { ui } from '@hozu/core'
import { admin } from '../../routes.ts'
import { route } from '@hozu/core'
import { z } from 'zod'

export const home = route({ path: '/notes', params: null, search: z.object({ q: z.string().default(''), limit: z.number().int().min(1).default(5) }) })
export const login = route({ path: '/login', params: null, search: z.object({ deleted: z.boolean().default(false) }) })
export const archive = route({ path: '/archive', params: null, search: null })
