import { event, invoke, machine, mutation, query, on, tag } from '@hozu/core'
import { z } from 'zod'

export const UserRow = z.object({ name: z.string(), notes: z.number(), readOnly: z.boolean() })
export const AccessMode = z.enum(['read-only', 'writable'])

export const usersTag = tag({ param: null })

// Every user who has signed in or owns notes, with how many notes they own (archived ones included) and whether
// their account is read-only. Only `admin`.
export const listUsers = query({
  input: z.object({}),
  output: z.array(UserRow),
  errors: { Unauthorized: z.object({}), NotAdmin: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [usersTag()],
  runs: 'server',
  access: 'anyone',
})

// Makes another user's account read-only or writable again. Only `admin`; the admin's own account stays writable.
export const setAccess = mutation({
  input: z.object({ name: z.string(), mode: AccessMode }),
  output: z.object({}),
  invalidates: () => [usersTag()],
  runs: 'server',
  access: { allow: ({ session }) => session.user === 'admin' },
})

export const SetAccess = event({ payload: z.object({ name: z.string(), mode: AccessMode }) })

export const NOT_ALLOWED = 'Not allowed'

export const adminMachine = machine({
  context: z.object({ name: z.string(), mode: AccessMode, error: z.string().nullable() }),
  initialContext: { name: '', mode: 'writable', error: null },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [on(SetAccess, { target: 'setting', assign: (e) => { ctx.name = e.name; ctx.mode = e.mode; ctx.error = null } })],
    },
    setting: {
      invoke: invoke(setAccess, {
        input: { name: ctx.name, mode: ctx.mode },
        done: 'idle',
        failed: {
          Forbidden: { target: 'idle', assign: () => { ctx.error = NOT_ALLOWED } },
          Invalid: { target: 'idle', assign: (e) => { ctx.error = e.message } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
  }),
})
EOF
cat > features/admin/server.ts <<'EOF'
import type { Implement } from '@hozu/data'
import { listUsers, setAccess } from './model.ts'

// `owned` counts each owner's notes (archived included); `seen` is everyone who has signed in; `readOnly` holds the
// accounts the admin made read-only.
export function adminResolvers<Env>(implement: Implement<{ user: string }, Env>, owned: () => Map<string, number>, seen: Set<string>, readOnly: Set<string>) {
  return [
    implement(listUsers, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      if (session.user !== 'admin') return fail('NotAdmin', {})
      const counts = owned()
      for (const user of seen) if (!counts.has(user)) counts.set(user, 0)
      return [...counts]
        .map(([name, notes]) => ({ name, notes, readOnly: readOnly.has(name) }))
        .sort((a, b) => a.name.localeCompare(b.name))
    }),
    implement(setAccess, ({ name, mode }, { fail }) => {
      const user = name.trim().toLowerCase()
      if (user === 'admin') return fail('Invalid', { message: 'The admin account stays writable', fields: { name: 'The admin account stays writable' } })
      if (mode === 'read-only') readOnly.add(user)
      else readOnly.delete(user)
      return {}
    }),
  ]
}
EOF
